head.b:skin:
/*-----------------------------------------------
Blogger Theme Name: NextVarsity DU MCQ Portal
Author: NextVarsity
-----------------------------------------------*/
body {
  margin: 0;
  padding: 0;
  font-family: 'Plus Jakarta Sans', 'Hind Siliguri', sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
  -webkit-font-smoothing: antialiased;
}
h1, h2, h3, .font-display {
  font-family: 'Outfit', 'Hind Siliguri', sans-serif;
}
.du-green { color: #006a4e; }
.du-red { color: #de2b3c; }
.bg-du-green { background-color: #006a4e; }
.bg-du-purple { background-color: #746294; }

/* Hide default Blogger navbar and gadgets */
.navbar, #navbar, .header-widget, .blog-pager, .post-footer, #comments, #sidebar-wrapper {
  display: none !important;
}

@media print {
  body { background: #fff !important; }
  .no-print { display: none !important; }
  .print-card {
    box-shadow: none !important;
    border: 1px solid #94a3b8 !important;
    margin: 0 !important;
    padding: 10px !important;
    width: 100% !important;
  }
}

