// Question Bank
var DEFAULT_QUESTIONS = {
  physics: [
    { id: 'p1', subjectId: 'physics', questionBn: 'একটি প্রাসের সর্বাধিক অনুভূমিক পাল্লার জন্য নিক্ষেপণ কোণ কত হতে হবে?', options: ['30°', '45°', '60°', '90°'], correctIndex: 1, category: 'knowledge', chapter: 'গতিবিদ্যা', explanation: 'R = (v₀² sin 2θ)/g। sin 2θ = 1 হলে θ = 45°।' },
    { id: 'p2', subjectId: 'physics', questionBn: 'দুটি সমমানের ভেক্টরের লব্ধির মান এদের যেকোনো একটির মানের সমান হলে মধ্যবর্তী কোণ কত?', options: ['60°', '90°', '120°', '180°'], correctIndex: 2, category: 'math', chapter: 'ভেক্টর', explanation: 'R² = 2P²(1 + cos θ) ⇒ cos θ = -1/2 ⇒ θ = 120°।' },
    { id: 'p3', subjectId: 'physics', questionBn: 'সরল ছন্দিত কণার বিস্তার A হলে, কোথায় গতিশক্তি ও স্থিতিশক্তি সমান হবে?', options: ['A/2', 'A/√2', 'A/4', '√3A/2'], correctIndex: 1, category: 'math', chapter: 'পর্যাবৃত্ত গতি', explanation: '1/2 k(A² - x²) = 1/2 k x² ⇒ x = A/√2।' },
    { id: 'p4', subjectId: 'physics', questionBn: 'কার্নো ইঞ্জিনের কর্মদক্ষতা 100% হতে হলে তাপ গ্রাহকের পরম তাপমাত্রা কত হতে হবে?', options: ['0°C', '273 K', '0 K', '100 K'], correctIndex: 2, category: 'comprehension', chapter: 'তাপগতিবিদ্যা', explanation: 'η = 1 - T₂/T₁। η = 1 হলে T₂ = 0 K।' },
    { id: 'p5', subjectId: 'physics', questionBn: 'একটি ধারকের দুই প্রান্তের বিভব পার্থক্য দ্বিগুণ করা হলে সঞ্চিত শক্তি কত গুণ হবে?', options: ['2 গুণ', '4 গুণ', 'অপরিবর্তিত', '8 গুণ'], correctIndex: 1, category: 'comprehension', chapter: 'স্থির তড়িৎ', explanation: 'U = 1/2 C V²। V দ্বিগুণ হলে U চারগুণ হয়।' },
    { id: 'p6', subjectId: 'physics', questionBn: 'একটি তারকে টেনে দৈর্ঘ্য দ্বিগুণ করা হলে নতুন রোধ আদি রোধের কত গুণ হবে?', options: ['2 গুণ', '4 গুণ', '1/2 গুণ', '1/4 গুণ'], correctIndex: 1, category: 'math', chapter: 'চল তড়িৎ', explanation: 'R\' = n² R = 2² R = 4R।' }
  ],
  chemistry: [
    { id: 'c1', subjectId: 'chemistry', questionBn: 'নিচের কোন অণুর জ্যামিতিক আকৃতি ত্রিকোণাকার পিরামিডীয়?', options: ['BF₃', 'CH₄', 'NH₃', 'H₂O'], correctIndex: 2, category: 'comprehension', chapter: 'মৌলের পর্যায়বৃত্ত ধর্ম ও রাসায়নিক বন্ধন', explanation: 'NH₃ তে ৩টি বন্ধনজোড় ও ১টি মুক্তজোড় ইলেকট্রন থাকে।' },
    { id: 'c2', subjectId: 'chemistry', questionBn: 'STP-তে 16 গ্রাম মিথেন (CH₄) গ্যাসের আয়তন কত লিটার?', options: ['11.2 L', '22.4 L', '44.8 L', '24.78 L'], correctIndex: 1, category: 'math', chapter: 'পরিবেশ রসায়ন', explanation: '16g CH₄ = 1 mol = 22.4 L at STP।' },
    { id: 'c3', subjectId: 'chemistry', questionBn: 'নিচের কোনটি ইলেকট্রোফাইল হিসেবে কাজ করে?', options: ['NH₃', 'H₂O', 'AlCl₃', 'CN⁻'], correctIndex: 2, category: 'knowledge', chapter: 'জৈব রসায়ন', explanation: 'AlCl₃-তে অষ্টক অপূর্ণ থাকায় এটি ইলেকট্রোফাইল।' },
    { id: 'c4', subjectId: 'chemistry', questionBn: 'হাইড্রোজেনের বামার সিরিজের রেখাসমূহ কোন অঞ্চলে দেখা যায়?', options: ['অতিবেগুনি (UV)', 'দৃশ্যমান (Visible)', 'অবলোহিত (IR)', 'এক্স-রে'], correctIndex: 1, category: 'knowledge', chapter: 'গুণগত রসায়ন', explanation: 'বামার সিরিজ দৃশ্যমান (Visible) অঞ্চলে দেখা যায়।' },
    { id: 'c5', subjectId: 'chemistry', questionBn: '0.001 M HCl দ্রবণের pH এর মান কত?', options: ['1', '2', '3', '4'], correctIndex: 2, category: 'math', chapter: 'রাসায়নিক পরিবর্তন (সাম্যাবস্থা)', explanation: 'pH = -log(0.001) = 3।' },
    { id: 'c6', subjectId: 'chemistry', questionBn: 'বেনজিনের নাইট্রেশনে কোন ইলেকট্রোফাইলটি অংশগ্রহণ করে?', options: ['NO⁺', 'NO₂⁺', 'NO₂⁻', 'NO₃⁻'], correctIndex: 1, category: 'comprehension', chapter: 'জৈব রসায়ন', explanation: 'নাইট্রোনিয়াম আয়ন (NO₂⁺) ইলেকট্রোফাইল।' }
  ],
  math: [
    { id: 'm1', subjectId: 'math', questionBn: 'মান নির্ণয় কর: lim (x → 0) (sin 5x) / (3x)', options: ['1', '5/3', '3/5', '0'], correctIndex: 1, category: 'math', chapter: 'অন্তরীকরণ (Calculus)', explanation: '(5/3) × lim (sin 5x / 5x) = 5/3।' },
    { id: 'm2', subjectId: 'math', questionBn: 'y = x³ - 3x² + 2 বক্ররেখার কোন বিন্দুতে স্পর্শকের ঢাল শূন্য হবে?', options: ['x = 0 ও x = 2', 'x = 1 ও x = -1', 'x = 0 ও x = 3', 'x = 2 ও x = -2'], correctIndex: 0, category: 'math', chapter: 'অন্তরীকরণ (Calculus)', explanation: 'dy/dx = 3x² - 6x = 0 ⇒ x = 0, 2।' },
    { id: 'm3', subjectId: 'math', questionBn: '∫ dx / (1 + x²) এর মান কোনটি?', options: ['ln(1 + x²) + C', 'tan⁻¹(x) + C', 'sin⁻¹(x) + C', 'cot⁻¹(x) + C'], correctIndex: 1, category: 'knowledge', chapter: 'যোগজীকরণ (Integration)', explanation: 'd/dx(tan⁻¹ x) = 1/(1+x²)।' },
    { id: 'm4', subjectId: 'math', questionBn: 'উপবৃত্তের সমীকরণ x²/25 + y²/16 = 1 হলে এর উৎকেন্দ্রিকতা কত?', options: ['3/5', '4/5', '9/25', '5/3'], correctIndex: 0, category: 'math', chapter: 'কণিক (Conics)', explanation: 'e = √(1 - 16/25) = 3/5।' },
    { id: 'm5', subjectId: 'math', questionBn: 'ম্যাট্রিক্স A = [[2, 3], [1, 4]] হলে |A| এর মান কত?', options: ['5', '11', '8', '-5'], correctIndex: 0, category: 'math', chapter: 'ম্যাট্রিক্স ও নির্ণায়ক', explanation: '|A| = 8 - 3 = 5।' },
    { id: 'm6', subjectId: 'math', questionBn: '3x + 4y - 12 = 0 সরলরেখাটি অক্ষদ্বয়ের সাথে যে ত্রিভুজ উৎপন্ন করে তার ক্ষেত্রফল কত?', options: ['6 বর্গ একক', '12 বর্গ একক', '24 বর্গ একক', '7 বর্গ একক'], correctIndex: 0, category: 'math', chapter: 'সরলরেখা', explanation: 'x/4 + y/3 = 1। ক্ষেত্রফল = 1/2 × 4 × 3 = 6।' }
  ],
  biology: [
    { id: 'b1', subjectId: 'biology', questionBn: 'কোষের শক্তিঘর (Powerhouse of the cell) বলা হয় কোন অঙ্গাণুকে?', options: ['রাইবোজোম', 'মাইটোকন্ড্রিয়া', 'গলগি বডি', 'লাইসোজোম'], correctIndex: 1, category: 'knowledge', chapter: 'কোষ ও এর গঠন', explanation: 'মাইটোকন্ড্রিয়াতে প্রচুর ATP তৈরি হয়।' },
    { id: 'b2', subjectId: 'biology', questionBn: 'মায়োসিসের কোন উপপর্যায়ে ক্রসিং ওভার সম্পন্ন হয়?', options: ['লেপটোটিন', 'জাইগোটিন', 'প্যাকাইটিন', 'ডিপ্লোটিন'], correctIndex: 2, category: 'comprehension', chapter: 'কোষ বিভাজন', explanation: 'প্যাকাইটিন উপপর্যায়ে ক্রসিং ওভার ঘটে।' },
    { id: 'b3', subjectId: 'biology', questionBn: 'মানবদেহে ইউরিয়া সংশ্লেষিত হয় প্রধানত কোন অঙ্গে?', options: ['বৃক্ক', 'যকৃৎ', 'প্লীহা', 'ফুসফুস'], correctIndex: 1, category: 'knowledge', chapter: 'রেচন ও বর্জ্য', explanation: 'যকৃতে অরনিথিন চক্রের মাধ্যমে ইউরিয়া উৎপন্ন হয়।' },
    { id: 'b4', subjectId: 'biology', questionBn: 'মেন্ডেলের দ্বিতীয় সূত্রের ফিনোটাইপিক অনুপাত কোনটি?', options: ['3 : 1', '9 : 3 : 3 : 1', '12 : 3 : 1', '9 : 7'], correctIndex: 1, category: 'comprehension', chapter: 'জিনতত্ত্ব ও বিবর্তন', explanation: 'ডাইহাইব্রিড ক্রসের অনুপাত 9:3:3:1।' },
    { id: 'b5', subjectId: 'biology', questionBn: 'রক্তের গ্লুকোজের মাত্রা হ্রাস করতে সাহায্য করে কোন হরমোন?', options: ['গ্লুকাগন', 'ইনসুলিন', 'থাইরক্সিন', 'অ্যাড্রেনালিন'], correctIndex: 1, category: 'knowledge', chapter: 'রক্ত ও সংবহন', explanation: 'ইনসুলিন গ্লুকোজ হ্রাস করে।' },
    { id: 'b6', subjectId: 'biology', questionBn: 'DNA অণুর গুয়ানিন (G) ও সাইটোসিন (C) এর মধ্যে কয়টি হাইড্রোজেন বন্ধন থাকে?', options: ['1টি', '2টি', '3টি', '4টি'], correctIndex: 2, category: 'knowledge', chapter: 'কোষ ও এর গঠন', explanation: 'G ও C এর মাঝে ৩টি হাইড্রোজেন বন্ধন থাকে।' }
  ],
  bangla: [
    { id: 'bn1', subjectId: 'bangla', questionBn: '\'বিদ্যালয়\' শব্দটির সঠিক সন্ধি বিচ্ছেদ কোনটি?', options: ['বিদ্ + আলয়', 'বিদ্যা + আলয়', 'বিদ্য + আলয়', 'বিদ্যা + লয়'], correctIndex: 1, category: 'knowledge', explanation: 'বিদ্যা + আলয় = বিদ্যালয়।' },
    { id: 'bn2', subjectId: 'bangla', questionBn: '\'অপরিচিতা\' গল্পের কল্যাণীর পিতার নাম কী?', options: ['হরিশ', 'শম্ভুনাথ সেন', 'অনুপম', 'বিনুদা'], correctIndex: 1, category: 'knowledge', explanation: 'কল্যাণীর পিতা শম্ভুনাথ সেন।' },
    { id: 'bn3', subjectId: 'bangla', questionBn: '\'পঙ্কজ\' কোন সমাস?', options: ['দ্বন্দ্ব', 'উপপদ তৎপুরুষ', 'কর্মধারয়', 'বহুব্রীহি'], correctIndex: 1, category: 'comprehension', explanation: 'পঙ্কে জন্মে যা = পঙ্কজ (উপপদ তৎপুরুষ)।' },
    { id: 'bn4', subjectId: 'bangla', questionBn: 'যে নারীর স্বামী ও পুত্র নেই—এক কথায় প্রকাশ কী হবে?', options: ['অসূর্যম্পশ্যা', 'বীরা', 'অবীরা', 'অনূঢ়া'], correctIndex: 2, category: 'knowledge', explanation: 'স্বামী ও পুত্রহীন নারীকে অবীরা বলে।' },
    { id: 'bn5', subjectId: 'bangla', questionBn: 'শুদ্ধ বানান কোনটি?', options: ['মুহুর্ত', 'মুহূর্ত', 'মুহুর্থ', 'মুহুর্ত্ত'], correctIndex: 1, category: 'knowledge', explanation: 'শুদ্ধ বানান হলো মুহূর্ত।' }
  ],
  english: [
    { id: 'e1', subjectId: 'english', questionBn: 'He is adept ___ solving complex mathematical problems.', options: ['in', 'at', 'with', 'for'], correctIndex: 1, category: 'knowledge', explanation: 'Adept at something.' },
    { id: 'e2', subjectId: 'english', questionBn: 'Choose the correct synonym of "BENEVOLENT":', options: ['Malicious', 'Altruistic', 'Indifferent', 'Hostile'], correctIndex: 1, category: 'knowledge', explanation: 'Benevolent means altruistic/kind.' },
    { id: 'e3', subjectId: 'english', questionBn: 'Neither the teacher nor the students ___ present.', options: ['was', 'were', 'has been', 'is'], correctIndex: 1, category: 'comprehension', explanation: 'Agrees with closer plural subject (students were).' },
    { id: 'e4', subjectId: 'english', questionBn: 'Meaning of idiom "A bolt from the blue":', options: ['Pleasant surprise', 'Sudden shock', 'Lightning flash', 'Blue sky'], correctIndex: 1, category: 'knowledge', explanation: 'An unexpected sudden event.' },
    { id: 'e5', subjectId: 'english', questionBn: 'If she had worked hard, she ___ the examination.', options: ['will pass', 'would pass', 'would have passed', 'had passed'], correctIndex: 2, category: 'comprehension', explanation: 'Third conditional: would have + past participle.' }
