};

// State variables
var selectedSubjects = ['physics', 'chemistry', 'math', 'biology'];
var mainSubject = 'math';
var optionalSubject = 'biology';
var candidateName = 'Md. Rafiqul Islam';
var examRoll = '1142715';
var activeQuestions = [];
var userAnswers = {};
var timerSeconds = 1200;
var timerInterval = null;
var subjectChapterModes = { physics: 'all', chemistry: 'all', math: 'all', biology: 'all' };
var subjectSelectedChapters = { physics: [], chemistry: [], math: [], biology: [] };

function initApp() {
  renderChapterCheckboxes('physics');
  renderChapterCheckboxes('chemistry');
  renderOptionalSubjects();
}

function generateNewRoll() {
  var r = Math.floor(1100000 + Math.random() * 899999);
  document.getElementById('inp-cand-roll').value = r;
}

function renderChapterCheckboxes(sub) {
  var box = document.getElementById(sub + '-chapters-box');
  if (!box) return;
  box.innerHTML = '';
  var chaps = HSC_CHAPTERS[sub] || [];
  chaps.forEach(function(ch) {
    var lbl = document.createElement('label');
    lbl.className = 'flex items-center gap-1.5 p-1 hover:bg-slate-50 cursor-pointer';
    lbl.innerHTML = '<input type="checkbox" value="' + ch + '" onchange="toggleChapterSelect(\'' + sub + '\', \'' + ch + '\')"/><span>' + ch + '</span>';
    box.appendChild(lbl);
  });
}

function setChapterMode(sub, mode) {
  subjectChapterModes[sub] = mode;
  var box = document.getElementById(sub + '-chapters-box');
  if (box) {
    if (mode === 'custom') box.classList.remove('hidden');
    else box.classList.add('hidden');
  }
}

function toggleChapterSelect(sub, ch) {
  var arr = subjectSelectedChapters[sub] || [];
  var idx = arr.indexOf(ch);
  if (idx >= 0) arr.splice(idx, 1);
  else arr.push(ch);
  subjectSelectedChapters[sub] = arr;
}

function onMainSubjectChange(sub) {
  mainSubject = sub;
  if (sub === 'math') {
    document.getElementById('label-main-math').className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2.5 bg-emerald-50/50 border-[#006a4e]';
    document.getElementById('label-main-bio').className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2.5 border-slate-200 bg-white';
  } else {
    document.getElementById('label-main-bio').className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2.5 bg-emerald-50/50 border-[#006a4e]';
    document.getElementById('label-main-math').className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2.5 border-slate-200 bg-white';
  }
  renderOptionalSubjects();
}

function renderOptionalSubjects() {
  var container = document.getElementById('opt-subjects-container');
  if (!container) return;
  container.innerHTML = '';

  var options = mainSubject === 'math'
    ? [{ id: 'biology', name: 'Biology (জীববিজ্ঞান)' }, { id: 'bangla', name: 'Bangla (বাংলা)' }, { id: 'english', name: 'English (ইংরেজি)' }]
    : [{ id: 'math', name: 'Higher Math (উচ্চতর গণিত)' }, { id: 'bangla', name: 'Bangla (বাংলা)' }, { id: 'english', name: 'English (ইংরেজি)' }];

  optionalSubject = options[0].id;

  options.forEach(function(opt, idx) {
    var isChecked = idx === 0;
    var label = document.createElement('label');
    label.id = 'opt-lbl-' + opt.id;
    label.className = isChecked ? 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2 bg-emerald-50/50 border-[#006a4e]' : 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2 border-slate-200 bg-white';
    label.innerHTML = '<input type="radio" name="optSub" value="' + opt.id + '" ' + (isChecked ? 'checked' : '') + ' onchange="onOptSubjectChange(\'' + opt.id + '\')"/><span class="font-bold text-slate-800 text-xs">' + opt.name + '</span>';
    container.appendChild(label);
  });
}

function onOptSubjectChange(sub) {
  optionalSubject = sub;
  ['math', 'biology', 'bangla', 'english'].forEach(function(id) {
    var el = document.getElementById('opt-lbl-' + id);
    if (el) {
      if (id === sub) el.className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2 bg-emerald-50/50 border-[#006a4e]';
      else el.className = 'p-3 border-2 rounded-lg cursor-pointer flex items-center gap-2 border-slate-200 bg-white';
    }
  });
}

// Format time
function fmtTime(sec) {
  var m = Math.floor(sec / 60);
  var s = sec % 60;
  return (m < 10 ? '0' + m : m) + ':' + (s < 10 ? '0' + s : s);
}

// Question selection: picks 5 questions balancing categories
function pickBalanced5(pool, filterChaps) {
  var cPool = pool.slice();
  if (filterChaps && filterChaps.length > 0) {
    var filtered = cPool.filter(function(q) { return q.chapter && filterChaps.indexOf(q.chapter) >= 0; });
    if (filtered.length >= 5) cPool = filtered;
  }
  if (cPool.length <= 5) return cPool.slice(0, 5);

  var know = cPool.filter(function(q) { return (q.category || 'knowledge') === 'knowledge'; });
  var comp = cPool.filter(function(q) { return q.category === 'comprehension'; });
  var math = cPool.filter(function(q) { return q.category === 'math'; });

  var picked = [];
  if (know.length > 0) picked.push(know.pop());
  if (comp.length > 0) picked.push(comp.pop());
  if (math.length > 0) picked.push(math.pop());

  var rest = know.concat(comp, math).sort(function() { return 0.5 - Math.random(); });
  while (picked.length < 5 && rest.length > 0) {
    picked.push(rest.pop());
  }
  return picked.sort(function() { return 0.5 - Math.random(); });
}

function startExamNow() {
  candidateName = document.getElementById('inp-cand-name').value.trim() || 'DU Aspirant';
  examRoll = document.getElementById('inp-cand-roll').value.trim() || '1142715';
  selectedSubjects = ['physics', 'chemistry', mainSubject, optionalSubject];

  // Pick questions
  activeQuestions = [];
  userAnswers = {};

  selectedSubjects.forEach(function(sub) {
    var pool = DEFAULT_QUESTIONS[sub] || [];
    var filterChaps = subjectChapterModes[sub] === 'custom' ? subjectSelectedChapters[sub] : null;
    var picked = pickBalanced5(pool, filterChaps);
    activeQuestions = activeQuestions.concat(picked);
  });

  // Set up exam view
  document.getElementById('disp-cand-name').innerText = candidateName;
  document.getElementById('disp-cand-roll').innerText = '(Roll: ' + examRoll + ')';
  renderExamQuestions();

  // Switch view
  document.getElementById('view-select').classList.add('hidden');
  document.getElementById('view-result').classList.add('hidden');
  document.getElementById('view-exam').classList.remove('hidden');
  document.getElementById('header-timer-wrap').classList.remove('hidden');
  window.scrollTo(0, 0);

  // Start active timer
  timerSeconds = 1200;
  if (timerInterval) clearInterval(timerInterval);
  timerInterval = setInterval(function() {
    timerSeconds--;
    var tStr = fmtTime(timerSeconds);
    document.getElementById('header-timer-val').innerText = tStr;
    document.getElementById('exam-timer-val').innerText = tStr;

    if (timerSeconds <= 0) {
      clearInterval(timerInterval);
      executeFinalSubmit();
    }
  }, 1000);
}

function renderExamQuestions() {
  var listEl = document.getElementById('exam-questions-list');
  listEl.innerHTML = '';
  var optLetters = ['ক', 'খ', 'গ', 'ঘ'];

  activeQuestions.forEach(function(q, idx) {
    var qCard = document.createElement('div');
    qCard.className = 'bg-white p-4 sm:p-5 rounded-xl border border-slate-300';

    // Note: Category badges removed from exam question card per User Request 2
    var html = '<div class="flex items-start gap-2 mb-3">' +
      '<span class="font-bold text-sm bg-slate-100 text-slate-800 w-6 h-6 rounded flex items-center justify-center shrink-0">' + (idx + 1) + '.</span>' +
      '<div class="flex-1 font-bold text-sm sm:text-base text-slate-900 leading-snug">' + q.questionBn + '</div>' +
      '</div>' +
      '<div class="grid grid-cols-1 sm:grid-cols-2 gap-2 mt-2 sm:pl-8">';

    q.options.forEach(function(opt, oIdx) {
      html += '<label class="p-3 rounded-lg border border-slate-200 hover:border-slate-300 min-h-[44px] cursor-pointer flex items-center gap-2.5 text-xs sm:text-sm active:bg-slate-50">' +
        '<input type="radio" name="q_' + q.id + '" value="' + oIdx + '" class="h-4 w-4 text-[#006a4e] shrink-0" onchange="recordAnswer(\'' + q.id + '\', ' + oIdx + ')"/>' +
        '<span class="font-bold text-slate-500 shrink-0">(' + optLetters[oIdx] + ')</span>' +
        '<span class="flex-1">' + opt + '</span>' +
        '</label>';
    });

    html += '</div>';
    qCard.innerHTML = html;
    listEl.appendChild(qCard);
  });

  updateAnswerProgress();
}

function recordAnswer(qId, oIdx) {
  userAnswers[qId] = oIdx;
  updateAnswerProgress();
}

function updateAnswerProgress() {
  var cnt = Object.keys(userAnswers).length;
  var str = cnt + ' / ' + activeQuestions.length + ' সম্পন্ন';
  document.getElementById('disp-answered-cnt').innerText = str;
  document.getElementById('bottom-answered-text').innerText = 'মোট উত্তর দিয়েছেন: ' + cnt + ' / ' + activeQuestions.length;
}

function openSubmitConfirmModal() {
  var cnt = Object.keys(userAnswers).length;
  document.getElementById('modal-ans-cnt').innerText = cnt + 'টি';
  document.getElementById('modal-unans-cnt').innerText = (activeQuestions.length - cnt) + 'টি';
  document.getElementById('modal-time-left').innerText = fmtTime(timerSeconds);
  document.getElementById('modal-submit-confirm').classList.remove('hidden');
}

function closeSubmitConfirmModal() {
  document.getElementById('modal-submit-confirm').classList.add('hidden');
}

function executeFinalSubmit() {
  closeSubmitConfirmModal();
  if (timerInterval) clearInterval(timerInterval);

  // Compute score (pure MCQ marks without written marks)
  var totalCorrect = 0;
  var totalWrong = 0;
  var subjectScores = {};

  selectedSubjects.forEach(function(s) {
    subjectScores[s] = { correct: 0, wrong: 0, mcqMarks: 0 };
  });

  activeQuestions.forEach(function(q) {
    var userChoice = userAnswers[q.id];
    if (userChoice !== undefined) {
      if (userChoice === q.correctIndex) {
        totalCorrect++;
        if (subjectScores[q.subjectId]) subjectScores[q.subjectId].correct++;
      } else {
        totalWrong++;
        if (subjectScores[q.subjectId]) subjectScores[q.subjectId].wrong++;
      }
    }
  });

  var totalMarks = Math.max(0, totalCorrect * 1.0 - totalWrong * 0.25);
  var isPassed = totalMarks >= 8.0;
  var meritPos = Math.floor(totalMarks >= 15 ? (100 + Math.random() * 800) : (2000 + Math.random() * 6000));

  // Populate Result Card
  document.getElementById('res-card-roll').innerText = examRoll;
  document.getElementById('res-card-status').innerHTML = isPassed ? '<span class="text-[#008000] font-extrabold text-base">PASSED</span>' : '<span class="text-red-600 font-extrabold text-base">NOT PASSED</span>';
  document.getElementById('res-card-merit').innerText = isPassed ? (meritPos + ' (Science)') : 'Not Qualified';
  document.getElementById('res-card-total').innerText = totalMarks.toFixed(2);

  document.getElementById('res-stat-correct').innerText = totalCorrect + 'টি';
  document.getElementById('res-stat-wrong').innerText = totalWrong + 'টি';
  document.getElementById('res-stat-time').innerText = fmtTime(1200 - timerSeconds);
  document.getElementById('res-stat-name').innerText = candidateName;

  // Details Table: Subjects | (Correct) MCQ (Wrong) | Marks (NO written marks)
  var tbody = document.getElementById('res-details-tbody');
  tbody.innerHTML = '';

  selectedSubjects.forEach(function(s) {
    var sc = subjectScores[s] || { correct: 0, wrong: 0 };
    var net = Math.max(0, sc.correct * 1.0 - sc.wrong * 0.25).toFixed(2);
    var c2d = (sc.correct < 10 ? '0' : '') + sc.correct;
    var w2d = (sc.wrong < 10 ? '0' : '') + sc.wrong;

    var subName = s === 'physics' ? 'Physics' : s === 'chemistry' ? 'Chemistry' : s === 'math' ? 'Mathematics' : s === 'biology' ? 'Biology' : s === 'bangla' ? 'Bangla' : 'English';

    var tr = document.createElement('tr');
    tr.className = 'divide-x divide-slate-200';
    tr.innerHTML = '<td class="py-2.5 px-3 font-semibold text-left text-slate-800">' + subName + '</td>' +
      '<td class="py-2.5 px-3 font-mono"><span class="text-[#008000] font-bold">✓' + c2d + '</span> <span class="text-base font-bold font-serif mx-2">' + net + '</span> <span class="text-red-600 font-bold">×' + w2d + '</span></td>' +
      '<td class="py-2.5 px-3 font-mono font-bold text-slate-900">' + net + '</td>';
    tbody.appendChild(tr);
  });

  // Switch to result view
  document.getElementById('view-exam').classList.add('hidden');
  document.getElementById('header-timer-wrap').classList.add('hidden');
  document.getElementById('view-result').classList.remove('hidden');
  window.scrollTo(0, 0);

  // Celebration confetti if passed!
  if (isPassed && window.confetti) {
    window.confetti({ particleCount: 70, spread: 60, origin: { y: 0.6 } });
  }

  // Save result to localStorage
  try {
    var hist = JSON.parse(localStorage.getItem('nextvarsity_hist') || '[]');
    hist.unshift({ roll: examRoll, name: candidateName, marks: totalMarks.toFixed(2), passed: isPassed, merit: meritPos, date: new Date().toLocaleDateString() });
    localStorage.setItem('nextvarsity_hist', JSON.stringify(hist.slice(0, 20)));
  } catch(e) {}
}

function appGoHome() {
  if (timerInterval) clearInterval(timerInterval);
  document.getElementById('view-exam').classList.add('hidden');
  document.getElementById('view-result').classList.add('hidden');
  document.getElementById('header-timer-wrap').classList.add('hidden');
  document.getElementById('view-select').classList.remove('hidden');
  window.scrollTo(0, 0);
}

function openAdminModal() { document.getElementById('modal-admin').classList.remove('hidden'); }
function closeAdminModal() { document.getElementById('modal-admin').classList.add('hidden'); }
function openHistoryModal() {
  var listEl = document.getElementById('history-list');
  listEl.innerHTML = '';
  var hist = JSON.parse(localStorage.getItem('nextvarsity_hist') || '[]');
  if (hist.length === 0) {
    listEl.innerHTML = '<div class="text-center py-4 text-slate-400">কোনো পূর্ববর্তী রেকর্ড নেই</div>';
  } else {
    hist.forEach(function(h) {
      var d = document.createElement('div');
      d.className = 'p-2.5 rounded border border-slate-200 flex justify-between';
      d.innerHTML = '<div><span class="font-bold font-mono">Roll: ' + h.roll + '</span> <span class="ml-2 font-bold ' + (h.passed ? 'text-[#006a4e]' : 'text-red-600') + '">' + (h.passed ? 'PASSED' : 'NOT PASSED') + '</span><div class="text-slate-400 text-[10px]">' + h.date + '</div></div><div class="font-bold font-mono text-sm">' + h.marks + '/20</div>';
      listEl.appendChild(d);
    });
  }
  document.getElementById('modal-history').classList.remove('hidden');
}
function closeHistoryModal() { document.getElementById('modal-history').classList.add('hidden'); }

function adminSaveQuestion(e) {
  e.preventDefault();
  var sub = document.getElementById('adm-sub').value;
  var cat = document.getElementById('adm-cat').value;
  var chap = document.getElementById('adm-chap').value.trim();
  var qBn = document.getElementById('adm-q-bn').value.trim();
  var o0 = document.getElementById('adm-opt-0').value.trim();
  var o1 = document.getElementById('adm-opt-1').value.trim();
  var o2 = document.getElementById('adm-opt-2').value.trim();
  var o3 = document.getElementById('adm-opt-3').value.trim();
  var exp = document.getElementById('adm-exp').value.trim();
  var radios = document.getElementsByName('adm_correct');
  var correctIdx = 0;
  for (var i = 0; i < radios.length; i++) { if (radios[i].checked) correctIdx = parseInt(radios[i].value); }

  var newQ = { id: 'custom_' + Date.now(), subjectId: sub, questionBn: qBn, options: [o0, o1, o2, o3], correctIndex: correctIdx, category: cat, chapter: chap, explanation: exp };
  if (!DEFAULT_QUESTIONS[sub]) DEFAULT_QUESTIONS[sub] = [];
  DEFAULT_QUESTIONS[sub].push(newQ);

  alert('প্রশ্ন সফলভাবে যোগ করা হয়েছে!');
  closeAdminModal();
  document.getElementById('admin-add-form').reset();
}

// Run initialization
window.onload = initApp;
